            'the #827 hint words stay retracted (gh-1446 AC1)',
      );
      expect(
        live,
        contains(RegExp(r'^─{30,}\s*$', multiLine: true)),
        reason:
            'the reserved fold row renders as a plain rule — chrome, '
            'not content (gh-1446 AC1 byte-scan contract)',
